/**
 * `honey-codegen generate --app <module>[#export]` (bit 19 h2, carry-in #1): the app module loaded through jiti and its
 * OpenAPI document generated by the app's own core, `@lovrozagar/honey/openapi`, resolved from the app as it would be
 * at run time, so gen imports no core itself (H2). The named export, else `app`, else `default`, is the app; the
 * module's `openApi` export, if any, is the document's options (core's GenerateOpenApiOptions), else a bare `info`.
 * Under Bun the module loads natively (Bun's own loaders); a core checkout is read from its source; with no core
 * installed where the app resolves it, the refusal names it.
 */
import { existsSync, readFileSync } from "node:fs"
import { dirname, join, relative, resolve } from "node:path"
import { createJiti } from "jiti"

const isBun = typeof (globalThis as { Bun?: unknown }).Bun !== "undefined"
const CORE = "@lovrozagar/honey"
const DEFAULT_OPTIONS = { info: { title: "API", version: "0.0.0" } }

/** `<module>[#export]` as its module path and the export it names, if any. */
export function appRef(ref: string): { module: string; name: string | undefined } {
	const at = ref.lastIndexOf("#")
	return at < 0 ? { module: ref, name: undefined } : { module: ref.slice(0, at), name: ref.slice(at + 1) || undefined }
}

/** The core package root the module at `from` resolves, found the way Node looks: up each node_modules. */
function coreRoot(from: string): string | undefined {
	for (let dir = dirname(from); ; dir = dirname(dir)) {
		const root = join(dir, "node_modules", CORE)
		if (existsSync(join(root, "package.json"))) return root
		if (dirname(dir) === dir) return undefined
	}
}

/** A core checkout's (it keeps tsconfig.json, which is never published) public subpaths aliased to their source. */
function sourceAliases(root: string): Record<string, string> | undefined {
	if (!existsSync(join(root, "tsconfig.json"))) return undefined
	const { exports = {} } = JSON.parse(readFileSync(join(root, "package.json"), "utf8")) as {
		exports?: Record<string, { "honey-source"?: string } | string>
	}
	const aliases: Record<string, string> = {}
	for (const [subpath, target] of Object.entries(exports)) {
		const source = typeof target === "object" ? target["honey-source"] : undefined
		if (source !== undefined) aliases[CORE + subpath.slice(1)] = join(root, source)
	}
	return aliases
}

/** The app `name` (else `app`, else `default`) of the loaded module `mod`, or why there is none. */
function appOf(mod: Record<string, unknown>, ref: string, name: string | undefined): unknown {
	const app = name === undefined ? (mod.app ?? mod.default) : mod[name]
	if (typeof (app as { fetch?: unknown } | null)?.fetch === "function") return app
	const which = name === undefined ? "no `app` or `default` export" : `no export ${JSON.stringify(name)}`
	throw new Error(`--app ${ref}: ${which} that is a honey app (name one as <module>#<export>)`)
}

/** The OpenAPI document of the app `ref` names, by the app's own core; `cwd` resolves it. One load at a time per process. */
export async function loadAppDocument(ref: string, cwd: string): Promise<Record<string, unknown>> {
	const { module, name } = appRef(ref)
	const path = resolve(cwd, module)
	if (!existsSync(path)) throw new Error(`--app ${ref}: ${relative(cwd, path)} does not exist`)
	const root = coreRoot(path)
	if (root === undefined)
		throw new Error(`--app ${ref}: no ${CORE} is installed where ${relative(cwd, path)} resolves it`)
	/* one module cache: the app and its document share core's module, so its GRAPH symbol */
	const jiti = createJiti(path, { alias: sourceAliases(root), fsCache: false, interopDefault: true, tryNative: isBun })
	const mod = (await jiti.import(path)) as Record<string, unknown>
	const app = appOf(mod, ref, name)
	const { generateOpenApi } = (await jiti.import(`${CORE}/openapi`)) as {
		generateOpenApi: (app: unknown, options: unknown) => Record<string, unknown>
	}
	return generateOpenApi(app, mod.openApi ?? DEFAULT_OPTIONS)
}
